def _entry_room(plan: FloorPlan, level_index: int) -> str | None:
    level = plan.level_at(level_index)
    if level is None:
        return None
    for wall in level.walls:
        for opening in wall.openings:
            if opening.kind is OpeningKind.MAIN_DOOR:
