/* ═══ PHONES ═══════════════════════════════════════════════════════════
   One column, thumb-sized targets, no horizontal scroll, and the page can
   still be scrolled with a finger resting on a drawing. */
@media (max-width: 700px) {
  html { -webkit-text-size-adjust: 100%; }
  body { overflow-x: hidden; }

  /* the brief */
  .compose > .compose__title { height: 64svh; min-height: 0; padding-bottom: 20px; }
  .headline__hard { font-size: clamp(34px, 11vw, 48px); }
  .headline__soft { font-size: clamp(20px, 6vw, 26px); }
  .headline__hard--sm { font-size: clamp(16px, 5vw, 20px); }
  .compose__title .headline { max-width: 100%; }
  .chat { height: auto; min-height: 0; padding-top: 20px; padding-bottom: calc(18px + env(safe-area-inset-bottom)); }
  .brief-strip { flex-wrap: wrap; gap: 8px; }
  .brief-strip__facts { flex-basis: 100%; }
  .brief-strip__act { flex: 1 1 100%; margin-left: 0; gap: 8px; }
  .brief-strip__act .link-btn { min-height: 44px; }
  .btn--start { flex: 1; margin-left: 0; height: 48px; }
  .composer__send, .composer__attach { width: 44px; height: 44px; }
  .msg--you { max-width: 86%; }
  .msg--atri { max-width: 100%; }
  .explain { padding-left: 16px; padding-right: 16px; }

  /* forms: 16px fields so iOS does not zoom on focus */
  input:not([type="radio"]):not([type="checkbox"]):not([type="range"]):not([type="file"]),
  select, textarea { font-size: max(16px, 1em); }

  /* the studio bar: wordmark and New brief, then schemes, then views */
  .bar { grid-template-columns: minmax(0, 1fr) auto; column-gap: 10px; }
  .wordmark { order: 1; }
  .bar__end { order: 2; }
  .bar__mid { order: 3; grid-column: 1 / -1; justify-content: flex-start; overflow-x: auto; scrollbar-width: none; }
  .bar__mid::-webkit-scrollbar { display: none; }
  .schemes { flex-wrap: nowrap; }
  .scheme-tab { flex: none; min-height: 40px; }
  .views { order: 4; scrollbar-width: none; }
