  .view-tab { flex: none; min-height: 40px; }
  .engine { display: none; }
  .bar__end .btn { min-height: 40px; padding: 0 14px; }

  /* the stage leaves room to scroll past it */
  .stage { height: 60svh; }
  .at-stage { height: 52svh; }
  .plate { min-height: 52svh; }
  .editdrawer { max-width: 100vw; width: 100vw; }
  .review { padding-bottom: env(safe-area-inset-bottom); }
}
